        _err(f"implement run-dispatch: cursor coder selected at Step 0 but CURSOR_PRESENT={cursor_present} in session-env; refusing Step 2 dispatch because that would silently override bootstrap routing")
        return 2
    child = [
        sys.executable,
        str(Path(plugin_root) / "python" / "cli.py"),
        "implement",
        "step2-dispatch",
        "--tmpdir",
        str(tmpdir),
        "--plan-file",
        str(plan_file),
        "--feature-file",
        str(feature_file),
        "--coder",
        args.coder,
        "--cursor-present",
        cursor_present,
    ]
    if args.answers:
        child.extend(["--answers", args.answers])
    env = os.environ.copy()
    env["CLAUDE_PLUGIN_ROOT"] = plugin_root
    env["IMPLEMENT_TMPDIR"] = str(tmpdir)
    result = subprocess.run(child, text=True, capture_output=True, env=env, check=False)
    if result.stdout:
        stream = logging_util.contract_stream()
        stream.write(result.stdout)
        stream.flush()
    if result.stderr:
        _err(result.stderr.rstrip("\n"))
    return result.returncode


